mapper.insert:
INSERT INTO manga_provider_call_gate(config_id, window_started_at, window_requests, consecutive_failures, created_by, updated_by)
VALUES (#{configId}, CURRENT_TIMESTAMP, 0, 0, #{actor}, #{actor})
ON DUPLICATE KEY UPDATE config_id = #{configId}

mapper.update:
UPDATE manga_provider_call_gate SET window_started_at = #{gate.windowStartedAt}, window_requests = #{gate.windowRequests},
consecutive_failures = #{gate.consecutiveFailures}, open_until = #{gate.openUntil}, updated_at = CURRENT_TIMESTAMP, updated_by = #{actor}
WHERE config_id = #{gate.configId}

UPDATE manga_model_call_ledger SET settled_usd = #{amount}, settled_by = #{userId}, settled_at = #{now},
settlement_note = #{note}, updated_at = CURRENT_TIMESTAMP, updated_by = #{userId}
WHERE call_id = #{callId} AND status != 'STARTED' AND settled_usd IS NULL

mapper.select:
SELECT id, call_id, run_id, step_id, owner_epoch, config_id, model_name, blueprint_fingerprint, status, usage_reported, input_tokens, output_tokens, cached_tokens, reasoning_tokens, cache_creation_tokens, tool_use_prompt_tokens, input_price, cached_input_price, output_price, reserved_usd, calculated_usd, settled_usd, settled_by, settled_at, settlement_note, failure_type, started_at, expires_at, finished_at, created_at, updated_at, created_by, updated_by FROM manga_model_call_ledger WHERE run_id = #{runId}
AND id < #{beforeId}
ORDER BY id DESC LIMIT 100

SELECT a.id, a.change_set_id, a.status, a.expires_at, a.decided_by, a.decided_at, a.comment,
a.created_at, a.updated_at, a.created_by, a.updated_by FROM manga_creative_approval a
JOIN manga_creative_change_set c ON c.change_set_id = a.change_set_id WHERE c.run_id = #{runId} ORDER BY a.id LIMIT #{limit}
